static int uya_windows_console_write(HANDLE h, const char *buf, size_t count) {
    wchar_t *wide;
    int n = 0, done = 0, chars = 0;
    size_t bytes = 0, i = 0;
    if (count == 0) return 0;
    wide = (wchar_t *)malloc(sizeof(wchar_t) * (count + 1));
    if (wide == NULL) return -1;
    n = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, buf, (int)count, wide, (int)(count + 1));
    if (n <= 0) { free(wide); return -1; }
    while (done < n) {
        DWORD chunk = 0;
        if (WriteConsoleW(h, wide + done, (DWORD)(n - done), &chunk, NULL) == 0) {
            free(wide);
            return -1;
        }
        if (chunk == 0) break;
        done += (int)chunk;
    }
    free(wide);
    while (i < count && chars < done) {
        unsigned char c = (unsigned char)buf[i];
        size_t step = 1;
        if (c >= 0xF0) step = 4;
        else if (c >= 0xE0) step = 3;
        else if (c >= 0xC0) step = 2;
        if (i + step > count) step = count - i;
        i += step;
        bytes += step;
        chars++;
    }
    return (int)bytes;
}
