static const char str395[] = "static inline int64_t uya_syscall0(int64_t n) {\n";
static const char str396[] = "    long ret;\n";
static const char str397[] = "    __asm__ volatile(\"syscall\" : \"=a\"(ret) : \"a\"(n) : \"rcx\", \"r11\", \"cc\", \"memory\");\n";
static const char str398[] = "    return ret;\n";
static const char str399[] = "}\n";
static const char str400[] = "static inline int64_t uya_syscall1(int64_t n, int64_t a1) {\n";
static const char str401[] = "    __asm__ volatile(\"syscall\" : \"=a\"(ret) : \"a\"(n), \"D\"(a1) : \"rcx\", \"r11\", \"cc\", \"memory\");\n";
