// std.thread：宿主工具链间接调用（跨 -O0/-O2 稳定；见 lib/std/thread.uya）
int32_t uya_call0_i32(void *fn) {
    typedef int32_t (*uya_fn0_i32)(void);
    return ((uya_fn0_i32)fn)();
}
int32_t uya_call0_i32_stack(void *fn, void *stack_top) {
    typedef int32_t (*uya_fn0_i32)(void);
#if defined(__x86_64__) || defined(_M_X64)
    uintptr_t top = ((uintptr_t)stack_top) & ~(uintptr_t)0xFUL;
    int32_t ret;
    __asm__ volatile(
        "mov %%rsp, %%rbx\n\t"
        "mov %1, %%rsp\n\t"
        "call *%2\n\t"
        "mov %%rbx, %%rsp\n\t"
        : "=a"(ret)
        : "r"((void *)top), "r"(fn)
        : "rbx", "rcx", "rdx", "rsi", "rdi", "r8", "r9", "r10", "r11", "memory", "cc");
    return ret;
#elif defined(__aarch64__) || defined(_M_ARM64)
    uintptr_t top = ((uintptr_t)stack_top) & ~(uintptr_t)0xFUL;
    int32_t ret;
    __asm__ volatile(
        "mov x9, sp\n\t"
        "mov sp, %1\n\t"
        "blr %2\n\t"
        "mov %w0, w0\n\t"
        "mov sp, x9\n\t"
        : "=r"(ret)
        : "r"((void *)top), "r"(fn)
        : "x0", "x9", "x30", "memory", "cc");
    return ret;
#else
    (void)stack_top;
    return ((uya_fn0_i32)fn)();
#endif
}
int32_t uya_thread_call_i32(void *fn, int32_t arg) {
    typedef int32_t (*uya_thrd_fn_i32)(int32_t);
    return ((uya_thrd_fn_i32)fn)(arg);
}
uint32_t uya_thread_call_u32(void *fn, uint32_t arg) {
    typedef uint32_t (*uya_thrd_fn_u32)(uint32_t);
    return ((uya_thrd_fn_u32)fn)(arg);
}
size_t uya_thread_call_usize(void *fn, size_t arg) {
    typedef size_t (*uya_thrd_fn_usz)(size_t);
    return ((uya_thrd_fn_usz)fn)(arg);
}
#if defined(__GNUC__) || defined(__clang__)
#if defined(__APPLE__)
typedef int32_t (*uya_pipeline_worker_fn)(void);
int32_t uya_pipeline_worker_dispatch(void) {
    static uya_pipeline_worker_fn real_fn = (uya_pipeline_worker_fn)0;
    static int32_t looked_up = 0;
    if (looked_up == 0) {
        real_fn = (uya_pipeline_worker_fn)dlsym((void *)-2, "uya_pipeline_worker_main_if_requested");
        looked_up = 1;
    }
    if (real_fn == (uya_pipeline_worker_fn)0) return -1;
    return real_fn();
}
#else
extern int32_t uya_pipeline_worker_main_if_requested(void) __attribute__((weak));
int32_t uya_pipeline_worker_dispatch(void) {
    if (uya_pipeline_worker_main_if_requested == (void *)0) return -1;
    return uya_pipeline_worker_main_if_requested();
}
#endif
#else
int32_t uya_pipeline_worker_dispatch(void) { return -1; }
#endif
